export default function Home() {
  return (
    <section id="home" className="hero-section">
      <p className="eyebrow">Producción, grabación y mezcla vocal</p>
      <h1>Clareny</h1>
      <p className="intro">
        Ofrezco un servicio de grabación, mezcla y edición vocal con enfoque en que la canción suene bien, se entienda y conecte emocionalmente.
      </p>
      <div className="hero-actions">
        <a className="btn btn-primary" href="#services">Ver servicios</a>
        <a className="btn btn-secondary" href="#contact">Contactar por WhatsApp</a>
      </div>
    </section>
  );
}
